templates.common/home:
{# David Creator — home completa (one-page) #}
{{ header }}
<main class="dj">
{% include 'partial/theme-scene-block.twig' %}
{% for section in cms_home_sections|default([]) %}
  {% if section == 'hero' %}{% include 'partial/hero.twig' %}
  {% elseif section == 'about' %}{% include 'partial/about.twig' %}
  {% elseif section == 'methodology' %}{% include 'partial/methodology.twig' %}
  {% elseif section == 'skills' %}{% include 'partial/skills.twig' %}
  {% elseif section == 'services' %}{% include 'partial/services.twig' %}
  {% elseif section == 'testimonials' %}{% include 'partial/testimonials.twig' %}
  {% elseif section == 'portfolio' %}{% include 'partial/portfolio.twig' %}
  {% elseif section == 'tools' %}{% include 'partial/tools.twig' %}
  {% elseif section == 'news' %}{% include 'partial/news.twig' %}
  {% elseif section == 'clients' %}{% include 'partial/clients.twig' %}
  {% elseif section == 'contact' %}{% include 'partial/contact.twig' %}
  {% endif %}
{% endfor %}
</main>
<div class="dj dj-cta">
  <h2>Are you ready to start a conversation?</h2>
  <p>I can help you promote your business with design, code and a visual identity that stands out.</p>
  <a class="dj-btn" href="mailto:contato@davidalmeida.xyz">Get in touch</a>
</div>
{{ footer }}

templates.partial/site_header:
{# David Creator — cabecalho + folha de estilo. Incluido por header.twig com only. #}
<style>
:root{
  --dj-primary:var(--theme-primary,#5cc6d0);
  --dj-surface:var(--theme-surface,#1b1f24);
  --dj-bg:#1b1f24;
  --dj-panel:#23282e;
  --dj-panel-2:#2a3037;
  --dj-line:rgba(92,198,208,.20);
  --dj-line-soft:rgba(255,255,255,.09);
  --dj-ink:#eef3f7;
  --dj-muted:#a7b2bd;
  --dj-dim:#7f8b96;
  --dj-font:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  --dj-display:system-ui,-apple-system,"Segoe UI Light","Segoe UI",Roboto,sans-serif;
  --dj-max:1100px;
  --dj-radius:4px;
}
*,*::before,*::after{box-sizing:border-box}
body{background:var(--dj-surface);color:var(--dj-ink);font-family:var(--dj-font);line-height:1.7;-webkit-font-smoothing:antialiased}
img{max-width:100%;height:auto;display:block}
a{color:var(--dj-primary);text-decoration:none}
a:hover{text-decoration:underline}
.dj{color:var(--dj-ink);font-family:var(--dj-font)}
.dj :focus-visible{outline:2px solid var(--dj-primary);outline-offset:3px}
.dj-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap}
.dj-wrap{max-width:var(--dj-max);margin:0 auto;padding:0 28px}

/* ── Tipografia display ─────────────────────────────────────── */
.dj-display{font-family:var(--dj-display);font-weight:200;letter-spacing:.14em;text-transform:uppercase;line-height:1.15}
.dj h1,.dj h2,.dj h3,.dj h4{margin:0 0 16px;font-family:var(--dj-display);font-weight:200;letter-spacing:.13em;text-transform:uppercase}
.dj h1{font-size:clamp(2.4rem,6vw,4.4rem)}
.dj h2{font-size:clamp(1.7rem,3.6vw,2.7rem)}
.dj h3{font-size:1.15rem;letter-spacing:.1em}
.dj h4{font-size:.98rem}
.dj p{color:var(--dj-muted);margin:0 0 16px}
.dj-rule{width:150px;height:1px;background:var(--dj-line);margin:22px auto;border:0}
.dj-kicker{font-size:.72rem;letter-spacing:.24em;text-transform:uppercase;color:var(--dj-primary);font-weight:600}

/* ── Cabeçalho ──────────────────────────────────────────────── */
.dj-header{position:sticky;top:0;z-index:30;background:rgba(20,24,28,.93);backdrop-filter:blur(10px);border-bottom:1px solid var(--dj-line-soft)}
.dj-header-in{max-width:var(--dj-max);margin:0 auto;padding:0 28px;display:flex;align-items:center;gap:24px;min-height:74px}
.dj-brand{display:inline-flex;align-items:center;gap:10px;color:#fff;white-space:nowrap}
.dj-brand:hover{text-decoration:none}
.dj-brand-mark{display:grid;place-items:center;width:36px;height:36px;border:1px solid var(--dj-primary);color:var(--dj-primary);font-weight:300;font-size:1.05rem;letter-spacing:.02em;transform:rotate(-4deg)}
.dj-brand-txt{display:flex;flex-direction:column;line-height:1.05;font-weight:300;letter-spacing:.16em;font-size:.86rem;text-transform:uppercase}
.dj-brand-txt b{font-weight:600;letter-spacing:.2em}
.dj-nav{display:flex;align-items:center;gap:2px;margin-left:auto;flex-wrap:wrap}
.dj-nav a{color:#d7dfe6;font-size:.72rem;font-weight:600;letter-spacing:.16em;text-transform:uppercase;padding:10px 11px}
.dj-nav a:hover{color:var(--dj-primary);text-decoration:none}
.dj-langs{display:flex;gap:7px;padding-left:14px;border-left:1px solid var(--dj-line-soft);font-size:.8rem}
.dj-langs a{color:var(--dj-dim)}
.dj-langs a.is-active{color:var(--dj-primary)}

/* ── Hero cósmico ───────────────────────────────────────────── */
.dj-hero{position:relative;overflow:hidden;min-height:620px;display:grid;place-items:center;text-align:center;
 background:radial-gradient(ellipse 70% 80% at 18% 22%,rgba(178,116,160,.42),transparent 62%),
            radial-gradient(ellipse 60% 70% at 84% 72%,rgba(58,110,170,.50),transparent 64%),
            radial-gradient(ellipse 90% 60% at 50% 110%,rgba(126,80,150,.32),transparent 70%),
            linear-gradient(135deg,#151a20,#232b36 55%,#141a22)}
.dj-hero::after{content:"";position:absolute;inset:0;
 background-image:radial-gradient(1px 1px at 12% 18%,rgba(255,255,255,.65),transparent),
  radial-gradient(1px 1px at 28% 62%,rgba(255,255,255,.45),transparent),
  radial-gradient(1.5px 1.5px at 68% 14%,rgba(255,255,255,.7),transparent),
  radial-gradient(1px 1px at 82% 44%,rgba(255,255,255,.5),transparent),
  radial-gradient(1px 1px at 46% 82%,rgba(255,255,255,.4),transparent),
  radial-gradient(1px 1px at 92% 78%,rgba(255,255,255,.5),transparent),
  radial-gradient(1px 1px at 6% 72%,rgba(255,255,255,.4),transparent);
 pointer-events:none}
.dj-hero-panel{position:relative;z-index:2;width:min(760px,92%);padding:60px 40px;background:rgba(16,20,24,.52);border:1px solid var(--dj-line-soft);box-shadow:0 24px 70px rgba(0,0,0,.35)}
.dj-hero-im{color:var(--dj-primary);font-size:1rem;letter-spacing:.5em;font-weight:200;text-transform:uppercase}
.dj-hero-line{width:200px;height:1px;background:rgba(255,255,255,.45);margin:18px auto}
.dj-hero-name{color:#fff;font-size:clamp(3rem,9vw,6.2rem);font-weight:200;letter-spacing:.16em;line-height:1.02;margin:0;text-transform:uppercase}
.dj-hero-last{color:var(--dj-primary);font-size:clamp(2.3rem,7vw,4.9rem);font-weight:200;letter-spacing:.13em;line-height:1.1;margin:0;text-transform:uppercase}
.dj-hero-role{color:var(--dj-primary);font-size:clamp(.8rem,1.8vw,1.15rem);letter-spacing:.42em;text-transform:uppercase;margin-top:18px;font-weight:300}
.dj-hero-social{display:flex;justify-content:center;flex-wrap:wrap;gap:16px;margin-top:34px;position:relative;z-index:2}
.dj-hero-social a{color:#cfd8e0;font-size:.72rem;letter-spacing:.16em;text-transform:uppercase;border-bottom:1px solid transparent;padding-bottom:3px}
.dj-hero-social a:hover{color:var(--dj-primary);border-color:var(--dj-primary);text-decoration:none}

/* ── Seções ─────────────────────────────────────────────────── */
.dj-section{padding:92px 0;border-bottom:1px solid var(--dj-line-soft);background:var(--dj-bg)}
.dj-section--alt{background:var(--dj-panel)}
.dj-section--cosmos{position:relative;overflow:hidden;
 background:radial-gradient(ellipse 60% 90% at 12% 20%,rgba(150,95,145,.28),transparent 65%),
            radial-gradient(ellipse 60% 90% at 88% 80%,rgba(52,105,160,.30),transparent 65%),
            var(--dj-panel-2)}
.dj-section-head{text-align:center;max-width:760px;margin:0 auto 52px}
.dj-section-head h2{color:#fff}
.dj-section-head .dj-kicker{display:block;margin-bottom:16px}
.dj-section-head p{font-size:1rem}
.dj-lead{font-size:1.05rem;color:#c9d3dc}
.dj-grid{display:grid;gap:22px}
.dj-grid--2{grid-template-columns:repeat(2,1fr)}
.dj-grid--3{grid-template-columns:repeat(3,1fr)}
.dj-grid--4{grid-template-columns:repeat(4,1fr)}
.dj-card{background:var(--dj-panel);border:1px solid var(--dj-line-soft);padding:26px;border-radius:var(--dj-radius);transition:border-color .18s ease,transform .18s ease}
.dj-card:hover{border-color:var(--dj-line);transform:translateY(-3px)}
.dj-card h3{color:#fff;margin-bottom:12px}
.dj-card p{font-size:.92rem;margin:0}
.dj-num{display:block;color:var(--dj-primary);font-size:.78rem;letter-spacing:.24em;margin-bottom:14px}
.dj-icon{width:38px;height:38px;border:1px solid var(--dj-line);display:grid;place-items:center;color:var(--dj-primary);margin-bottom:18px;border-radius:50%}
.dj-icon svg{width:19px;height:19px}
.dj-list{list-style:none;padding:0;margin:0;display:grid;gap:9px}
.dj-list li{color:var(--dj-muted);font-size:.92rem;padding-left:18px;position:relative}
.dj-list li::before{content:"";position:absolute;left:0;top:.72em;width:6px;height:1px;background:var(--dj-primary)}
.dj-tags{display:flex;flex-wrap:wrap;gap:9px;margin-top:18px}
.dj-tag{border:1px solid var(--dj-line);color:var(--dj-primary);font-size:.74rem;letter-spacing:.1em;text-transform:uppercase;padding:6px 12px;border-radius:2px}

/* ── Processo / etapas ──────────────────────────────────────── */
.dj-step{background:var(--dj-panel);border:1px solid var(--dj-line-soft);padding:24px;position:relative}
.dj-step-n{position:absolute;top:14px;right:18px;color:rgba(92,198,208,.22);font-size:2rem;font-weight:200;letter-spacing:0}
.dj-step h3{color:#fff;font-size:.96rem}
.dj-step p{font-size:.87rem;margin:0}

/* ── Portfólio ──────────────────────────────────────────────── */
.dj-work{background:var(--dj-panel);border:1px solid var(--dj-line-soft);overflow:hidden;display:block}
.dj-work:hover{text-decoration:none;border-color:var(--dj-line)}
.dj-work-art{aspect-ratio:16/10;display:grid;place-items:center;font-family:var(--dj-display);font-weight:200;letter-spacing:.2em;text-transform:uppercase;font-size:1.1rem;color:rgba(255,255,255,.86)}
.dj-work-art.a{background:radial-gradient(circle at 30% 25%,#4c6fa8,#202a3b 70%)}
.dj-work-art.b{background:radial-gradient(circle at 70% 30%,#8a5a3c,#2a211c 70%)}
.dj-work-art.c{background:radial-gradient(circle at 40% 70%,#3d7b5a,#1d2c24 70%)}
.dj-work-art.d{background:radial-gradient(circle at 60% 40%,#6d4b8f,#241d31 70%)}
.dj-work-art.e{background:radial-gradient(circle at 25% 60%,#a5713a,#2c2318 70%)}
.dj-work-art.f{background:radial-gradient(circle at 75% 70%,#3c7f95,#1a2a30 70%)}
.dj-work-body{padding:18px 20px}
.dj-work-body h3{color:#fff;font-size:.9rem;margin:0}
.dj-work-body span{color:var(--dj-dim);font-size:.76rem;letter-spacing:.1em;text-transform:uppercase}

/* ── Depoimentos ────────────────────────────────────────────── */
.dj-quote{background:var(--dj-panel-2);border-left:2px solid var(--dj-primary);padding:28px;margin:0}
.dj-quote p{color:#dbe4ec;font-size:.98rem;font-style:italic}
.dj-quote-by{display:flex;align-items:center;gap:12px;margin-top:18px}
.dj-avatar{width:38px;height:38px;border-radius:50%;border:1px solid var(--dj-line);color:var(--dj-primary);display:grid;place-items:center;font-size:.74rem;letter-spacing:.05em}
.dj-quote-by b{display:block;color:#fff;font-size:.86rem;font-weight:600}
.dj-quote-by span{color:var(--dj-dim);font-size:.78rem}

/* ── Clientes / ferramentas ─────────────────────────────────── */
.dj-clients{display:flex;flex-wrap:wrap;justify-content:space-around;gap:18px;padding:12px 0}
.dj-client{color:#9aa6b1;font-family:var(--dj-display);font-weight:300;letter-spacing:.18em;text-transform:uppercase;font-size:.92rem}
.dj-tool{border:1px solid var(--dj-line-soft);background:var(--dj-panel);padding:24px;text-align:center}
.dj-tool-mark{width:52px;height:52px;margin:0 auto 18px;border:1px solid var(--dj-line);border-radius:50%;display:grid;place-items:center;color:var(--dj-primary);font-weight:300;font-size:1.1rem}
.dj-tool h3{color:#fff;font-size:.94rem}
.dj-tool p{font-size:.86rem;margin-bottom:16px}
.dj-tool a{font-size:.74rem;letter-spacing:.14em;text-transform:uppercase;border-bottom:1px solid var(--dj-line);padding-bottom:3px}

/* ── CTA / botões ───────────────────────────────────────────── */
.dj-btn{display:inline-flex;align-items:center;justify-content:center;padding:13px 30px;background:var(--dj-primary);color:#101820;border:1px solid var(--dj-primary);font-size:.76rem;font-weight:700;letter-spacing:.18em;text-transform:uppercase;border-radius:2px;transition:background .16s ease,color .16s ease}
.dj-btn:hover{background:transparent;color:var(--dj-primary);text-decoration:none}
.dj-btn-ghost{display:inline-flex;align-items:center;justify-content:center;padding:12px 28px;border:1px solid var(--dj-line);color:var(--dj-primary);background:transparent;font-size:.76rem;font-weight:600;letter-spacing:.18em;text-transform:uppercase;border-radius:2px}
.dj-btn-ghost:hover{background:rgba(92,198,208,.09);text-decoration:none}
.dj a.dj-btn,.dj a.dj-btn:hover{color:#101820}
.dj a.dj-btn:hover{color:var(--dj-primary)}
.dj a.dj-btn-ghost,.dj a.dj-btn-ghost:hover{color:var(--dj-primary)}
.dj-cta{text-align:center;padding:80px 24px;background:linear-gradient(120deg,rgba(92,198,208,.10),rgba(140,90,160,.12)),var(--dj-panel)}
.dj-cta h2{color:#fff}
.dj-cta p{max-width:60ch;margin:0 auto 26px}

/* ── Páginas internas ───────────────────────────────────────── */
.dj-page{padding:64px 0 96px}
.dj-crumb{font-size:.76rem;letter-spacing:.14em;text-transform:uppercase;color:var(--dj-dim);margin-bottom:26px}
.dj-crumb a{color:var(--dj-dim)}
.dj-crumb span{margin:0 9px;color:var(--dj-primary)}
.dj-page-head{max-width:760px;margin-bottom:46px}
.dj-page-head h1{color:#fff;font-size:clamp(2rem,4.4vw,3.2rem)}
.dj-prose{max-width:760px}
.dj-prose h2{color:#fff;font-size:1.5rem;margin-top:38px}
.dj-prose p{font-size:1rem}
.dj-aside{background:var(--dj-panel);border:1px solid var(--dj-line-soft);padding:26px}
.dj-aside h3{color:#fff;font-size:.9rem}
.dj-aside a{display:block;padding:9px 0;border-bottom:1px solid var(--dj-line-soft);color:var(--dj-muted);font-size:.86rem}
.dj-aside a:last-of-type{border-bottom:0}
.dj-aside .dj-btn{margin-top:18px;width:100%}
.dj-contact-list{list-style:none;padding:0;margin:0;display:grid;gap:20px}
.dj-contact-list li{display:flex;gap:14px;align-items:flex-start}
.dj-contact-list svg{width:20px;height:20px;flex:0 0 20px;color:var(--dj-primary);margin-top:4px}
.dj-contact-list b{display:block;color:#fff;font-size:.76rem;letter-spacing:.16em;text-transform:uppercase;font-weight:600}
.dj-contact-list span{color:var(--dj-muted);font-size:.92rem}
.dj-404{text-align:center;padding:90px 0}
.dj-404-code{font-size:clamp(5rem,14vw,9rem);font-weight:200;color:var(--dj-primary);letter-spacing:.1em;line-height:1}

/* ── Rodapé ─────────────────────────────────────────────────── */
.dj-footer{background:#12161a;border-top:1px solid var(--dj-line);padding:56px 0 0}
.dj-footer-grid{display:grid;grid-template-columns:1.4fr 1fr 1fr 1.2fr;gap:36px;padding-bottom:42px}
.dj-footer h3{color:#fff;font-size:.78rem;letter-spacing:.2em;margin-bottom:18px}
.dj-footer p{font-size:.88rem;color:var(--dj-dim)}
.dj-footer a{display:block;color:var(--dj-muted);font-size:.86rem;padding:5px 0}
.dj-footer a:hover{color:var(--dj-primary)}
.dj-footer-bottom{border-top:1px solid var(--dj-line-soft);padding:20px 0;display:flex;justify-content:space-between;gap:14px;flex-wrap:wrap;font-size:.78rem;color:var(--dj-dim);letter-spacing:.06em}
.dj-footer-bottom a{display:inline;padding:0;color:var(--dj-dim)}
.dj-social{display:flex;flex-wrap:wrap;gap:12px;margin-top:16px}
.dj-social a{border:1px solid var(--dj-line-soft);padding:7px 11px;font-size:.7rem;letter-spacing:.12em;text-transform:uppercase;color:var(--dj-muted)}

/* ── Responsivo ─────────────────────────────────────────────── */
@media(max-width:980px){
 .dj-hero{min-height:520px}
 .dj-grid--4{grid-template-columns:repeat(2,1fr)}
 .dj-grid--3{grid-template-columns:repeat(2,1fr)}
 .dj-footer-grid{grid-template-columns:repeat(2,1fr)}
 .dj-langs{display:none}
}
@media(max-width:640px){
 .dj-wrap,.dj-header-in{padding:0 18px}
 .dj-header-in{min-height:auto;flex-wrap:wrap;gap:10px;padding-top:12px;padding-bottom:10px}
 .dj-nav{width:100%;margin-left:0;overflow-x:auto;flex-wrap:nowrap;padding-bottom:4px}
 .dj-nav a{padding:8px 9px;font-size:.66rem;white-space:nowrap}
 .dj-section{padding:60px 0}
 .dj-section-head{margin-bottom:34px}
 .dj-grid--2,.dj-grid--3,.dj-grid--4{grid-template-columns:1fr}
 .dj-hero{min-height:440px}
 .dj-hero-panel{padding:38px 18px;width:94%}
 .dj-hero-line{width:130px}
 .dj-hero-social{gap:10px}
 .dj-cta{padding:54px 18px}
 .dj-footer-grid{grid-template-columns:1fr;gap:26px}
}
@media(prefers-reduced-motion:reduce){
 .dj-card,.dj-btn{transition:none}
 .dj-card:hover{transform:none}
}
</style>
<div class="dj dj-header"><div class="dj-header-in">
  <a class="dj-brand" href="{{ home|default('/') }}" aria-label="David Creator"><span class="dj-brand-mark">DC</span><span class="dj-brand-txt"><b>David</b><span>Creator</span></span></a>
  <nav class="dj-nav" aria-label="Main navigation">
    <a href="{{ home|default('/') }}">{{ text_nav_home|default('Home') }}</a>
    <a href="{{ nav_about|default('#about') }}">{{ text_nav_about|default('About') }}</a>
    <a href="#services">Services</a><a href="{{ nav_portfolio|default('#works') }}">Works</a>
    <a href="{{ nav_blog|default('#news') }}">{{ text_nav_blog|default('Blog') }}</a>
    <a href="{{ nav_contact|default('#contact') }}">{{ text_nav_contact|default('Contact') }}</a>
    <a href="#tools">Tools</a><a href="#works">Alunos</a>
    <a href="{{ nav_quote|default('#contact') }}">Get in touch</a>
  </nav>
  <nav class="dj-langs" aria-label="{{ text_languages|default('Languages') }}">
    {% for lang in languages|default([]) %}<a class="dj-lang{{ lang.active ? ' is-active' : '' }}" href="{{ lang.href }}" hreflang="{{ lang.code }}">{{ lang.code }}</a>{% endfor %}
  </nav>
</div></div>
